#include "ksStateMultiSerializeTask.h"
#include <array>
#include <iostream>
#include <stdexcept>
using T=ks::StateMultiSerializeTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(unsigned seed=0;seed<65536;++seed){T task;unsigned reads=0,writes=0,clocks=0,children=0,globalWrites=0,selectionWrites=0,nameWrites=0,programWrites=0,currentSelections=0,restoreSelections=0;const unsigned storeClocks=seed&3;std::array<unsigned,4> programs{};for(unsigned p=0;p<4;++p)programs[p]=(seed*13+p*0x1234)&65535;auto field=[&](){return (seed*17+task.sourceGlobalOffset()*23)&255;};auto selection=[&](){return (seed*31+task.selection()*37)&255;};auto name=[&](){return (seed*41+task.part()*43+task.nameOffset()*47)&255;};
 auto read=[&](T::Read r)->unsigned{++reads;switch(r){case T::Read::Original:return 0xffa12345;case T::Read::GlobalField:return field();case T::Read::Selection:return selection();case T::Read::Name:return name();case T::Read::Program:return programs[task.part()];}return 0;};auto write=[&](T::Write w,uint32_t v){++writes;switch(w){case T::Write::GlobalField:check(globalWrites==task.globalField()&&task.targetGlobalOffset()==(globalWrites?task.sourceGlobalOffset():191)&&v==field(),"Serialized global field differs");++globalWrites;break;case T::Write::Selection:check(selectionWrites==task.selection()&&v==selection()&&globalWrites==7,"Selection mask order differs");++selectionWrites;break;case T::Write::Name:check(nameWrites/8==task.part()&&nameWrites%8==task.nameOffset()&&v==name(),"Part name sequence differs");++nameWrites;break;case T::Write::Bank:check(programWrites==task.part()*2&&v==(programs[task.part()]>>8),"Part bank differs");++programWrites;break;case T::Write::Program:check(programWrites==task.part()*2+1&&v==(programs[task.part()]&255),"Part program differs");++programWrites;break;case T::Write::SelectCurrent:check(currentSelections==task.part()&&programWrites==2*(task.part()+1),"Part pointer selection order differs");++currentSelections;break;case T::Write::SelectOriginal:check(currentSelections==4&&children==8,"Original context restored too early");++restoreSelections;break;}};
 while(!task.complete()){if(task.awaitingChild()){check(task.part()==children/2&&task.child()==(children%2?T::Child::PackedFields:T::Child::PartReference),"Part/packing child order differs");++children;check(task.resumeChild(),"Serialization child rejected");continue;}const auto c=task.nextClocks(storeClocks),before=reads,beforeWrites=writes;check(!task.advanceBefore(c-1,read,write,storeClocks)&&reads==before&&writes==beforeWrites,"Serialization early observation");check(task.advanceBefore(c,read,write,storeClocks)==c,"Serialization admission differs");clocks+=c;}
 if(clocks!=2127+49*storeClocks){std::cerr<<"clocks="<<clocks<<" expected="<<2127+49*storeClocks<<'\n';throw std::runtime_error("Serialization clocks differ");}check(reads==46&&writes==54&&globalWrites==7&&selectionWrites==2&&nameWrites==32&&programWrites==8&&restoreSelections==1&&children==8&&!task.resumeChild(),"Serialization full lifetime/counts differ");++cases;}
 std::cout<<"PASS: "<<cases<<" complete four-part multiset serialization jobs,late7global+2mask+32name+4program reads,8typed children,context restoration and exact ordered writes/clocks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
